// RGB renk karıştırma: 3 potansiyometre kırmızı, yeşil ve mavinin parlaklığını ayarlar.
// Ortak katotlu RGB LED: COM bacağı GND'de; renk pinine ne kadar PWM verilirse o renk o kadar parlar.
// Ortak anotlu LED kullanırsan COM'u 5V'a bağla ve ORTAK_ANOT değerini true yap.
const bool ORTAK_ANOT = false;

const int KIRMIZI_POT = A0;
const int YESIL_POT = A1;
const int MAVI_POT = A2;

const int KIRMIZI_PIN = 6;  // PWM pinleri (kartta ~ işareti)
const int YESIL_PIN = 5;
const int MAVI_PIN = 3;

const int BEKLE_MS = 100;   // iki okuma arası bekleme

// Potansiyometreyi okur, 0-255 parlaklığa çevirir, renk pinine yazar.
int rengiAyarla(int potPin, int ledPin) {
  int parlaklik = map(analogRead(potPin), 0, 1023, 0, 255);
  analogWrite(ledPin, ORTAK_ANOT ? 255 - parlaklik : parlaklik);
  return parlaklik;
}

void setup() {
  Serial.begin(9600);
  pinMode(KIRMIZI_PIN, OUTPUT);
  pinMode(YESIL_PIN, OUTPUT);
  pinMode(MAVI_PIN, OUTPUT);
}

void loop() {
  int r = rengiAyarla(KIRMIZI_POT, KIRMIZI_PIN);
  int g = rengiAyarla(YESIL_POT, YESIL_PIN);
  int b = rengiAyarla(MAVI_POT, MAVI_PIN);

  Serial.print("R: ");
  Serial.print(r);
  Serial.print("  G: ");
  Serial.print(g);
  Serial.print("  B: ");
  Serial.println(b);
  delay(BEKLE_MS);
}
